const fullDate=d=>new Date(d+'T12:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});
const toMinor=v=>{const s=String(v??'').trim();if(!/^-?\d+(\.\d{1,2})?$/.test(s))return null;let neg=s[0]==='-',a=s.replace('-','').split('.');let n=Number(a[0])*100+Number((a[1]||'').padEnd(2,'0'));return Number.isSafeInteger(n)?n*(neg?-1:1):null};
