let storage=true,db,storageIssue='',rawRecovery='';
try{const saved=localStorage.getItem('gally-v1');if(saved){rawRecovery=saved;db=JSON.parse(saved);if(!coreReadable(db))throw Error('Saved data could not be read');rawRecovery=''}else db=freshData()}catch(error){db=freshData();storage=false;storageIssue=rawRecovery?'damaged':'unavailable'}
