const ui={page:'home',currency:'GHS',month:'2026-11',homeTab:'today',search:'',filter:'all',accountFilter:'',catFilter:'',horizon:30,forecastAccount:'',scenario:false,late:0,incomeReduction:0,extra:0,loan:0,loanMonths:6,categoryKind:'expense'};
let draft=null,confirmAction=null,previousFocus=null,importBatch=null,restoreData=null,toastTimer;
function persist(){return safePersistExperience()}
function account(id){return db.accounts.find(a=>a.id===id)}
function cat(id){return db.categories.find(c=>c.id===id)||{name:'Uncategorised',icon:'other'}}
function activeTx(){return db.tx.filter(t=>!t.deleted)}
function balance(id){return (account(id)?.opening||0)+activeTx().filter(t=>t.account===id&&t.date<=TODAY).reduce((a,t)=>a+t.amount,0)}
function currencyAccounts(){return db.accounts.filter(a=>a.currency===ui.currency)}
function balanceCurrency(){return currencyAccounts().reduce((n,a)=>n+balance(a.id),0)}
function currencyTx(){return activeTx().filter(t=>account(t.account)?.currency===ui.currency)}
function monthTx(){return currencyTx().filter(t=>t.date.startsWith(ui.month)&&!t.pair)}
function monthTotal(sign){return monthTx().filter(t=>sign>0?t.amount>0:t.amount<0).reduce((a,t)=>a+Math.abs(t.amount),0)}
function spent(category){return monthTx().filter(t=>t.category===category&&t.amount<0).reduce((n,t)=>n-t.amount,0)}
function upcomingRules(days=7){return db.rules.filter(r=>account(r.account)?.currency===ui.currency).flatMap(r=>occurrences(r,days)).concat(subscriptionUpcoming(days)).sort((a,b)=>a.date.localeCompare(b.date))}
function nextDate(r,d){if(r.frequency==='weekly')return day(d,7);let x=new Date(d+'T12:00Z'),month=x.getUTCMonth()+1,year=x.getUTCFullYear();let target=new Date(Date.UTC(year,month+1,0)).getUTCDate();return new Date(Date.UTC(year,month,Math.min(Number(r.date.slice(-2)),target),12)).toISOString().slice(0,10)}
function occurrences(r,days){let out=[],d=r.date,i=0;while(d<=day(TODAY,days)&&i++<1000){if(d>=TODAY)out.push({...r,date:d});d=nextDate(r,d)}return out}
function safety(){let income=upcomingRules(180).find(r=>r.amount>0),until=income?.date||day(TODAY,30);let due=upcomingRules(Math.max(0,delta(until,TODAY))).filter(r=>r.amount<0&&r.date<until).reduce((n,r)=>n-r.amount,0);due+=currencyTx().filter(t=>t.date>TODAY&&t.date<until&&t.amount<0).reduce((n,t)=>n-t.amount,0);let reserved=db.goals.filter(g=>g.currency===ui.currency).reduce((n,g)=>n+g.saved,0);return {available:balanceCurrency(),due,reserved,until,income,safe:balanceCurrency()-due-reserved}}
function toast(msg){if(!storage&&!/session|backup|saved copy/i.test(msg))msg+=' Changes are in this session only.';$('#toast').innerHTML=icon(/saved|restored|received|imported|updated|loaded|ready/i.test(msg)?'check':'info')+`<span>${esc(msg)}</span>`;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000)}
function nav(page){ui.page=page;closeSheet(false);render();$('#content').scrollTop=0;$('#page-heading')?.focus({preventScroll:true})}
function iconBtn(name,action,label,extra=''){return `<button class="icon-btn ${extra}" data-action="${action}" aria-label="${esc(label)}">${icon(name)}</button>`}
function btn(label,action,cls='primary'){return `<button type="button" class="${cls}" data-action="${action}">${label}</button>`}
function empty(title,copy,action='add',label='Add a transaction'){return `<div class="empty"><div class="category-icon">${icon('ledger')}</div><h3>${title}</h3><p>${copy}</p>${btn(label,action)}</div>`}
function heading(title,sub='',action=''){return `<div class="page-head"><div class="screen-title-row"><h1 id="page-heading" tabindex="-1">${title}</h1>${action}</div>${sub?`<p>${sub}</p>`:''}</div>`}
function childHeading(title,back='home'){return `<div class="page-head back-title">${iconBtn('back','page:'+back,'Go back')}<h1 id="page-heading" tabindex="-1">${title}</h1></div>`}
function sectionHead(title,action,label='See all'){return `<div class="section-head"><h2>${title}</h2>${action?btn(label,action,'text-btn'):''}</div>`}
function txRow(t){let a=account(t.account),c=cat(t.category);return `<button class="list-row" data-action="edit:${t.id}"><span class="category-icon ${t.amount>0?'income':''}">${icon(t.pair?'transfer':c.icon)}</span><span class="od-field od-fill"><span class="title od-truncate">${esc(t.payee||c.name)}</span><small class="od-truncate">${esc(a?.name||'Account')} · ${esc(c.name)}</small></span><span class="od-field right od-fixed"><span class="money sensitive ${t.amount>0?'positive':''}">${money(t.amount,a.currency,true)}</span>${t.date>TODAY?'<small>Scheduled</small>':''}</span></button>`}
function budgetItem(b){return flexBudgetCard(b)}
function render(){try{ensurePlanning();if(renderExperience()){pipAfterRender();return;}document.documentElement.dataset.theme=db.theme;$('.app').classList.toggle('hidden-money',db.hidden);$('#topbar').innerHTML=`<button class="wordmark" data-action="page:home" aria-label="Gally home">${brand()}gally<span style="color:var(--primary)">.</span></button><div class="row">${iconBtn(db.theme==='dark'?'sun':'moon','theme','Switch to '+(db.theme==='dark'?'light':'dark')+' mode')}${iconBtn('eye','hide',db.hidden?'Show balances':'Hide balances')}${btn('A','page:settings','icon-btn avatar')}</div>`;let content={home:home,ledger:ledger,accounts:accounts,settings:settings,budgets:flexBudgetsScreen,subscriptions:subscriptionsScreen,talk:conversationScreen,companion:pipPreferencesScreen,appearance:appAppearanceScreen,notifications:notificationSettingsScreen,categories:categories,forecast:forecast,expected:expected,recurring:recurring,goals:goals,import:importScreen,activity:activity}[ui.page]||home;$('#content').innerHTML=content();$('#nav').innerHTML=['home','ledger','add','talk','accounts'].map(p=>p==='add'?`<button class="nav-add" data-action="add" aria-label="Add a transaction">${icon('plus')}</button>`:`<button class="nav-item ${ui.page===p||p==='talk'&&ui.page==='companion'?'active':''}" data-action="${p==='talk'?'talk-open':'page:'+p}" ${ui.page===p?'aria-current="page"':''}>${p==='talk'?pipBadge():icon(p)}<span>${p==='talk'?'Pip':p[0].toUpperCase()+p.slice(1)}</span></button>`).join('');enhanceExperience();enhancePlanning();pipAfterRender();}catch(error){renderAppFailure();}}
function home(){return `<div class="row between"><div><p class="greeting">Friday, 20 November</p><h1 id="page-heading" class="home-title" tabindex="-1">A little clarity.<br>A lot more calm.</h1></div></div><div class="segmented" style="margin:24px 0 0"><button data-action="home:today" class="${ui.homeTab==='today'?'selected':''}">Today</button><button data-action="home:plan" class="${ui.homeTab==='plan'?'selected':''}">Look ahead</button></div>${ui.homeTab==='plan'?planHome():todayHome()}`}
function todayHome(){let s=safety(),recent=activeTx().filter(t=>t.date<=TODAY).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id)).slice(0,5),bud=visibleBudgets();return `<section class="hero"><div class="hero-top"><span class="small">Money you have</span><button class="currency-btn" data-action="currency">${ui.currency}${icon('down')}</button></div><div class="amount number sensitive"><span class="currency">${ui.currency}</span>${balanceCurrency()<0?'−':''}${num(balanceCurrency())}</div><div class="row small">Across ${currencyAccounts().length} ${ui.currency} accounts</div><div class="hero-foot"><span class="row">${icon('shield')}On your phone. Always yours.</span>${icon('check')}</div></section><button class="safe-card" data-action="safe"><span class="safe-symbol">${icon('check')}</span><span class="od-field od-fill"><span class="small">${s.safe<0?'After commitments · shortfall':'Safe to spend'}</span><span class="money sensitive">${money(s.safe)}</span></span>${icon('chevron')}</button><div class="section">${sectionHead('On the horizon','home:plan','Look ahead')}${homeExpectedCard()}</div><div class="section">${sectionHead('This month','page:activity','Overview')}<div class="month-switch">${iconBtn('back','month:-1','Previous month')}<strong>${monthLabel()}</strong>${iconBtn('chevron','month:1','Next month',ui.month===MAX_MONTH?'future-disabled':'')}</div><div class="month-summary"><div class="od-stat"><small>Money in</small><span class="money positive sensitive">${money(monthTotal(1))}</span></div><div class="od-stat"><small>Money out</small><span class="money sensitive">${money(monthTotal(-1))}</span></div></div></div><div class="section">${sectionHead('Your budgets','page:budgets','Manage')}${bud.length?bud.slice(0,2).map(budgetItem).join(''):empty('Give your money a plan','Set a category budget for this month.','budget:new','Set a budget')}</div><div class="section">${sectionHead('Recent activity','page:ledger')}${recent.length?recent.map(txRow).join(''):empty('Your story starts here','Add your first spend, income or transfer.')}</div><p class="screen-footnote">Your money, your file. No paywall, ever.</p>`}
function monthLabel(){return new Date(ui.month+'-01T12:00Z').toLocaleDateString('en-GB',{month:'long',year:'numeric'})}
function planHome(){let rules=upcomingRules(),s=safety();return `<section class="hero"><span class="label">Your next chapter</span><h2 style="font-size:28px;margin:12px 0">Make room for<br>what matters.</h2><p class="small">Know what's committed. See what's possible.</p>${btn('Explore your forecast '+icon('arrow'),'page:forecast','text-btn')}</section><div class="section">${sectionHead('Next 7 days','page:recurring','All recurring')}${rules.length?rules.map(r=>`<button class="list-row" data-action="${r.subscription?'subscription':'rule'}:${r.id}"><span class="category-icon">${icon(r.amount>0?'income':cat(r.category).icon)}</span><span class="od-field od-fill"><strong class="title">${esc(r.name)}</strong><small>${dateText(r.date)} · ${esc(account(r.account).name)}</small></span><span class="money">${money(r.amount,ui.currency,true)}</span></button>`).join(''):empty('Nothing scheduled','Add a recurring payment to plan ahead.','rule:new','Add a recurring rule')}</div><div class="section">${sectionHead('Still on the way','page:expected','View expected')}${db.expected.filter(e=>account(e.account)?.currency===ui.currency).map(e=>`<button class="pending full" style="text-align:left;margin-bottom:12px" data-action="expected:${e.id}"><span class="row between"><strong>${esc(e.name)}</strong>${icon('chevron')}</span><span class="od-field" style="margin-top:8px"><span class="money">${money(e.amount)}</span><span class="small">${e.date<TODAY?delta(TODAY,e.date)+' days late':e.date===TODAY?'Due today':dateText(e.date)} · not in your balance</span></span></button>`).join('')||'<p class="help-block">Expected payments will appear here. They never count as money you already have.</p>'}</div><div class="section">${sectionHead('Little by little','page:goals','Your goals')}${db.goals.filter(g=>g.currency===ui.currency).map(goalCard).join('')||btn('Start a goal','goal:new','secondary full')}</div><div class="section card surface"><h3>What if payday is late?</h3><p class="help-block">Try a change without changing your ledger.</p>${btn('Try a scenario '+icon('arrow'),'scenario','text-btn')}</div>`}
function ledger(){let rows=activeTx().filter(t=>{let a=account(t.account),hay=(t.payee+' '+(t.raw||'')+' '+cat(t.category).name).toLowerCase();return hay.includes(ui.search.toLowerCase())&&(ui.filter==='all'||(ui.filter==='in'?t.amount>0:t.amount<0))&&(!ui.accountFilter||t.account===ui.accountFilter)&&(!ui.catFilter||t.category===ui.catFilter)}).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));let dates=[...new Set(rows.map(t=>t.date))];return heading('Your ledger','The everyday, all in one place.',iconBtn('plus','add','Add a transaction','soft'))+`<label class="field"><span class="small">Search transactions</span><input id="ledger-search" type="search" value="${esc(ui.search)}" placeholder="Payee, category or note"></label><div class="chips">${['all','in','out'].map(f=>`<button class="chip ${ui.filter===f?'selected':''}" data-action="filter:${f}">${f==='all'?'All':f==='in'?'Money in':'Money out'}</button>`).join('')}${btn(icon('settings')+' Filters','filters','chip')}</div><div id="ledger-results">${dates.length?dates.map(d=>`<h3 class="mini-label">${d===TODAY?'Today':d===day(TODAY,-1)?'Yesterday':fullDate(d)}</h3>${rows.filter(t=>t.date===d).map(txRow).join('')}`).join(''):empty(ui.search?'No matches yet':'A fresh page',ui.search?'Try another payee, category or note.':'Every small spend has a place here.')}</div>`}
function accounts(){return heading('Your pockets','Different places. One clear picture.',iconBtn('plus','account:new','Add an account','soft'))+db.accounts.map(a=>`<button class="account-card ${a.archived?'archived':''}" data-action="account:${a.id}"><span class="row between"><span class="row"><span class="category-icon">${icon(a.type==='Mobile money'?'airtime':a.type==='Cash'?'loan':'accounts')}</span><span class="od-field"><strong>${esc(a.name)}</strong><small>${esc(a.type)}${a.archived?' · Archived':''}</small></span></span><span class="badge">${a.currency}</span></span><span class="money sensitive">${money(balance(a.id),a.currency)}</span></button>`).join('')+(db.accounts.length?'':empty('Start with one pocket','Add a bank account, mobile money wallet or cash.','account:new','Add an account'))+`<p class="help-block">Balances come from your opening amounts and ledger. Different currencies are never added together.</p>`}
function settings(){const sr=(i,title,desc,action)=>`<button class="settings-row" data-action="${action}">${icon(i)}<span class="od-field od-fill"><strong>${title}</strong><small>${desc}</small></span>${icon('chevron')}</button>`;return heading('Make it yours','A quiet home for your money.')+`<div class="settings-group"><h2>Everyday</h2>${sr('accounts','Default currency',db.defaultCurrency+' · used for new accounts','default-currency')}${sr('moon','Appearance',db.theme==='light'?'Light · tap for dark':'Dark · tap for light','theme')}${sr('other','Categories','Make capture understand your words','page:categories')}${sr('goal','Budgets & goals','Give your money a little direction','page:budgets')}${sr('repeat','Recurring payments','Salary, bills and the everyday','page:recurring')}</div><div class="settings-group"><h2>Your file</h2>${sr('upload','Import a statement','Map columns, review, then confirm','page:import')}${sr('download','Export ledger CSV','Open your transactions in a spreadsheet','export-csv')}${sr('shield','Create a backup','Download a full prototype JSON backup','backup')}${sr('clock','Backup reminder',db.notifications?'In-app reminder enabled':'An in-app reminder, every 7 days','reminder')}${sr('trash','Recently removed','Your history stays in your file','removed')}</div><div class="settings-group"><h2>Take care</h2>${sr('upload','Restore a backup','Replaces this ledger after two confirmations','restore')}${sr('trash','Wipe money data','Keep preferences and import mappings','wipe')}${sr('plus','Load example data','Explore Gally without using real money','demo')}</div><div class="no-paywall"><div class="wordmark">${brand()}gally.</div><p>Your money, your file.</p><strong style="display:block;margin:16px 0 8px">No paywall, ever.</strong><p>Design prototype · v1.0<br>Example date: 20 November 2026</p></div><p class="screen-footnote">${storage?'Changes are saved in this browser on this device.':'Browser storage is unavailable. Changes last for this session.'}<br>Native app handoff: private SQLite file, no account.</p>`}
function budgets(){let list=db.budgets.filter(b=>b.currency===ui.currency&&b.month===ui.month);return childHeading('A little direction')+`<div class="row between"><button class="currency-btn" data-action="currency">${ui.currency}${icon('down')}</button>${btn('Goals '+icon('arrow'),'page:goals','text-btn')}</div><div class="month-switch">${iconBtn('back','month:-1','Previous month')}<strong>${monthLabel()}</strong>${iconBtn('chevron','month:1','Next month')}</div><p class="help-block">A budget is a plan, not a score. Adjust it as life changes.</p>${list.length?list.map(budgetItem).join(''):empty('A month with possibilities','Choose a category and give it a limit.','budget:new','Set a budget')}<div class="screen-actions">${btn(icon('plus')+' Set a budget','budget:new','secondary full')}</div>`}
function categories(){let list=db.categories.filter(c=>c.kind===ui.categoryKind);return childHeading('Your categories','settings')+`<p class="help-block">Teach Gally your words. “Chop bar” can mean food, automatically.</p><div class="segmented"><button data-action="category-kind:expense" class="${ui.categoryKind==='expense'?'selected':''}">Expenses</button><button data-action="category-kind:income" class="${ui.categoryKind==='income'?'selected':''}">Income</button></div>${list.map(c=>`<button class="list-row" data-action="category:${c.id}"><span class="category-icon">${icon(c.icon)}</span><span class="od-field od-fill"><strong>${esc(c.name)}</strong><small class="od-truncate">${esc(c.keywords||'Add your own keywords')}</small></span>${icon('chevron')}</button>`).join('')}<div class="screen-actions">${btn(icon('plus')+' New category','category:new','secondary full')}</div>`}
function expected(){let list=db.expected.filter(e=>account(e.account)?.currency===ui.currency);return childHeading('Money on the way')+`<div class="row between"><button class="currency-btn" data-action="currency">${ui.currency}${icon('down')}</button>${btn('Add expected','expected:new','text-btn')}</div><p class="help-block">A promise is a possibility. Expected money stays out of your balance until you confirm it arrived.</p>${list.map(e=>`<button class="pending full" style="margin:12px 0;text-align:left" data-action="expected:${e.id}"><span class="od-field"><strong>${esc(e.name)}</strong><span class="money" style="margin:8px 0">${money(e.amount)}</span><span class="small">${e.date<TODAY?delta(TODAY,e.date)+' days late':dateText(e.date)} · ${esc(account(e.account).name)}</span></span></button>`).join('')||empty('Nothing waiting in the wings','Add an expected payment when someone owes you.','expected:new','Add expected money')}`}
function recurring(){return childHeading('On repeat')+`<p class="help-block">Plan the predictable. Recurring rules shape your forecast; they never silently add transactions.</p>${db.rules.map(r=>`<button class="list-row" data-action="${r.subscription?'subscription':'rule'}:${r.id}"><span class="category-icon">${icon('repeat')}</span><span class="od-field od-fill"><strong>${esc(r.name)}</strong><small>${esc(r.frequency)} · next ${dateText(occurrences(r,365)[0]?.date||r.date)}</small></span><span class="money">${money(r.amount,account(r.account).currency,true)}</span></button>`).join('')||empty('Make space for the predictable','Add a salary or bill to see it in your forecast.','rule:new','Add a recurring rule')}<div class="screen-actions">${btn(icon('plus')+' Add recurring','rule:new','secondary full')}</div>`}
function goalCard(g){let months=Math.max(1,Math.ceil(delta(g.date,TODAY)/30)),remaining=Math.max(0,g.target-g.saved),monthly=Math.ceil(remaining/months);return `<button class="card goal-card full" data-action="goal:${g.id}" style="text-align:left"><span class="row"><span class="goal-art">${icon('laptop')}</span><span class="od-field od-fill"><strong>${esc(g.name)}</strong><small>By ${dateText(g.date)} ${g.date.slice(0,4)}</small></span>${icon('chevron')}</span><span class="od-field" style="margin-top:16px"><span class="money">${money(g.saved,g.currency)} <small class="muted">of ${money(g.target,g.currency)}</small></span></span><div class="budget-track"><div class="budget-fill" style="width:${Math.min(100,g.saved/g.target*100)}%"></div></div><p class="help-block" style="margin-bottom:0">${remaining?money(monthly,g.currency)+'/month to get there':'You made room for it. Goal reached.'}</p></button>`}
function goals(){return childHeading('For what matters')+`<p class="help-block">Set money aside in your plan. These reservations reduce safe-to-spend without moving money between accounts.</p>${db.goals.map(goalCard).join('')||empty('Something to look forward to','A new laptop, a rainy day, a little breathing room.','goal:new','Start a goal')}${btn(icon('plus')+' New goal','goal:new','secondary full')}`}
function forecastData(){let a=ui.forecastAccount,days=ui.horizon,rules=upcomingRules(days).filter(r=>!a||r.account===a),scheduled=currencyTx().filter(t=>t.date>TODAY&&(!a||t.account===a));let events=rules.map(r=>{let d=ui.scenario&&r.amount>0?day(r.date,ui.late):r.date;return {...r,date:d,amount:ui.scenario&&r.amount>0?Math.round(r.amount*(100-ui.incomeReduction)/100):r.amount,type:r.subscription?'Subscription':'Recurring'}}).concat(scheduled.map(t=>({...t,name:t.payee,type:'Scheduled'})));if(ui.scenario&&ui.extra>0)events.push({date:day(TODAY,1),amount:-ui.extra,name:'One-off spend',type:'Scenario'});if(ui.scenario&&ui.loan>0){events.push({date:TODAY,amount:ui.loan,name:'Loan received',type:'Scenario'});let installment=Math.floor(ui.loan/ui.loanMonths);for(let k=1;k<=ui.loanMonths;k++)events.push({date:day(TODAY,k*30),amount:-(k===ui.loanMonths?ui.loan-installment*(k-1):installment),name:'Loan repayment (no interest)',type:'Scenario'})}let current=a?balance(a):balanceCurrency(),arr=[],withExpected=[],value=current,poss=current;let exp=db.expected.filter(e=>account(e.account)?.currency===ui.currency&&(!a||e.account===a));for(let i=0;i<=days;i++){let d=day(TODAY,i);let add=events.filter(e=>e.date===d).reduce((n,e)=>n+e.amount,0);value+=add;poss+=add+exp.filter(e=>(e.date<TODAY?TODAY:e.date)===d).reduce((n,e)=>n+e.amount,0);arr.push(value);withExpected.push(poss)}return {arr,withExpected,events:events.sort((a,b)=>a.date.localeCompare(b.date)),dry:arr.findIndex(n=>n<0)}}
function forecastChart(data){let w=336,h=184,vals=[...data.arr,...data.withExpected],min=Math.min(0,...vals),max=Math.max(10000,...vals),range=max-min||1,pt=(v,i)=>`${(36+i/(data.arr.length-1)*286).toFixed(1)},${(148-(v-min)/range*120).toFixed(1)}`,line=data.arr.map((v,i)=>(i?'L':'M')+pt(v,i)).join(' '),extra=data.withExpected.map((v,i)=>(i?'L':'M')+pt(v,i)).join(' ');return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${ui.horizon} day balance forecast in ${ui.currency}. ${data.dry<0?'No shortfall in this projection.':'Runs dry on '+fullDate(day(TODAY,data.dry))+'.'}"><line class="axis" x1="36" x2="322" y1="28" y2="28"/><line class="axis" x1="36" x2="322" y1="88" y2="88"/><line class="axis" x1="36" x2="322" y1="148" y2="148"/><text x="0" y="32">High</text><text x="2" y="152">${min<0?'Low':'0'}</text><path class="area" d="${line} L322,148 L36,148 Z"/><path class="expected" d="${extra}"/><path class="actual" d="${line}"/><text x="36" y="178">Today</text><text x="160" y="178">${dateText(day(TODAY,Math.round(ui.horizon/2)))}</text><text x="285" y="178">${dateText(day(TODAY,ui.horizon))}</text></svg>`}
function forecast(){let data=forecastData();return childHeading(ui.scenario?'What if…':'A view ahead')+`<div class="row between"><button class="currency-btn" data-action="currency">${ui.currency}${icon('down')}</button><span class="badge">${ui.scenario?'Scenario · not saved':'A plan, not a guarantee'}</span></div><label class="field" style="margin-top:16px">Account<select id="forecast-account"><option value="">All ${ui.currency} accounts</option>${currencyAccounts().map(a=>`<option value="${a.id}" ${ui.forecastAccount===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><div class="chart-tabs">${[30,90,180].map(n=>`<button class="${ui.horizon===n?'selected':''}" data-action="horizon:${n}">${n} days</button>`).join('')}</div><div class="section"><span class="small muted">Projected on ${dateText(day(TODAY,ui.horizon))}</span><div class="amount number sensitive" style="margin-top:8px">${money(data.arr.at(-1))}</div><button class="text-btn ${data.dry>=0?'negative':''}" data-action="forecast-day:${data.dry>=0?data.dry:ui.horizon}">${icon(data.dry>=0?'alert':'check')}${data.dry>=0?'Runs dry on '+dateText(day(TODAY,data.dry)):'Covered across this projection'}</button>${forecastChart(data)}<div class="legend"><span><i></i>Scheduled + recurring</span><span><i class="dashed"></i>Including expected</span></div></div>${ui.scenario?`<div class="section card surface"><h3>Change the plan</h3><label class="field" style="margin-top:16px">Income delayed: <span id="late-label">${ui.late} days</span><input class="range" type="range" id="scenario-late" min="0" max="30" step="1" value="${ui.late}"></label><label class="field">Income reduced by <span>${ui.incomeReduction}%</span><input class="range" type="range" id="scenario-reduction" min="0" max="100" step="5" value="${ui.incomeReduction}"></label><label class="field">One-off spend (${ui.currency})<input id="scenario-extra" inputmode="decimal" value="${(ui.extra/100).toFixed(2)}"></label><details class="disclosure"><summary>Try a simple loan ${icon('down')}</summary><label class="field">Loan received (${ui.currency})<input id="scenario-loan" inputmode="decimal" value="${(ui.loan/100).toFixed(2)}"></label><label class="field">Monthly repayments<select id="scenario-months">${[3,6,12].map(n=>`<option value="${n}" ${ui.loanMonths===n?'selected':''}>${n} months</option>`).join('')}</select></label><p class="help-block">Principal only. No interest or fees are assumed.</p></details>${btn('Update scenario','scenario-update','primary full')}</div><div class="actions">${btn('Reset','scenario-reset','secondary')}${btn('Back to forecast','scenario-exit','secondary')}</div>`:`<div class="section">${btn('What if payday is 2 weeks late?','scenario','secondary full')}</div>`}<div class="section">${sectionHead('What shapes this view')}<p class="help-block">Starts with your recorded balances. The solid line includes dated future entries and recurring rules. The dashed line adds unreceived payments; overdue promises are assumed today only in that line. Daily spending you have not entered is not predicted.</p>${data.events.slice(0,12).map(e=>`<div class="list-row"><span class="od-field od-fill"><strong class="title">${esc(e.name)}</strong><small>${dateText(e.date)} · ${e.type}</small></span><span class="money">${money(e.amount,ui.currency,true)}</span></div>`).join('')}</div>`}
function activity(){let expenses=db.categories.filter(c=>c.kind==='expense').map(c=>({...c,total:spent(c.id)})).filter(c=>c.total>0).sort((a,b)=>a.id==='other'?1:b.id==='other'?-1:b.total-a.total),max=Math.max(1,...expenses.map(c=>c.total)),net=monthTotal(1)-monthTotal(-1);let trend=[];for(let i=5;i>=0;i--){let d=new Date(ui.month+'-01T12:00Z');d.setUTCMonth(d.getUTCMonth()-i);let m=d.toISOString().slice(0,7),ts=currencyTx().filter(t=>!t.pair&&t.date.startsWith(m));trend.push({label:d.toLocaleDateString('en-GB',{month:'short'}),income:ts.filter(t=>t.amount>0).reduce((n,t)=>n+t.amount,0),expense:ts.filter(t=>t.amount<0).reduce((n,t)=>n-t.amount,0)})}let peak=Math.max(1,...trend.flatMap(t=>[t.income,t.expense]));return childHeading('The month in view')+`<div class="month-switch">${iconBtn('back','month:-1','Previous month')}<strong>${monthLabel()}</strong>${iconBtn('chevron','month:1','Next month')}</div><button class="currency-btn" data-action="currency">${ui.currency}${icon('down')}</button><section class="hero"><small>${monthTx().length?'Income minus expenses':'No transactions this month'}</small><div class="amount number sensitive">${money(net)}</div><p class="small">${net>0?'More in than out.':net<0?'More out than in.':'Income and expenses are balanced.'}</p></section><div class="section"><h2>Where it went</h2><div class="spending-bars">${expenses.map(c=>`<div class="spending-bar"><span>${esc(c.name)}</span><div class="budget-track"><div class="budget-fill" style="width:${c.total/max*100}%"></div></div><span class="money right">${num(c.total)}</span></div>`).join('')||'<p class="help-block">No spending to show this month.</p>'}</div><p class="small muted">All amounts in ${ui.currency}. Transfers excluded.</p></div><div class="section"><h2>Six months, at a glance</h2><svg class="chart" viewBox="0 0 336 170" role="img" aria-label="Six month income and expense comparison in ${ui.currency}">${trend.map((t,i)=>{let x=22+i*52;return `<rect x="${x}" y="${140-t.income/peak*110}" width="12" height="${t.income/peak*110}" rx="3" fill="var(--primary)"/><rect x="${x+16}" y="${140-t.expense/peak*110}" width="12" height="${t.expense/peak*110}" rx="3" fill="var(--pending)"/><text x="${x}" y="162">${t.label}</text>`}).join('')}</svg><div class="legend"><span><i></i>Income</span><span><i style="border-color:var(--pending)"></i>Expenses</span></div>${trend.map(t=>`<details class="disclosure"><summary>${t.label} ${icon('down')}</summary><p>In: ${money(t.income)}<br>Out: ${money(t.expense)}</p></details>`).join('')}</div>`}
function openSheet(title,html){if($('#overlay').hidden)previousFocus=document.activeElement;$('#sheet-title').textContent=title;$('#sheet-body').innerHTML=html;$('#overlay').hidden=false;$('.app').inert=true;$('#sheet-close').focus();$('#sheet-body').scrollTop=0}
function closeSheet(focus=true){$('#overlay').hidden=true;$('.app').inert=false;confirmAction=null;if(focus){let el=previousFocus?.isConnected?previousFocus:$('#nav button');el?.focus({preventScroll:true})}}
function field(label,id,value='',type='text',help=''){return `<label class="field">${label}<input id="${id}" type="${type}" value="${esc(value)}" ${type==='text'&&id.includes('amount')?'inputmode="decimal"':''}>${help?`<span class="help">${help}</span>`:''}</label>`}
function accountSelect(id,selected='',currency='',includeArchived=false){let accounts=db.accounts.filter(a=>(includeArchived||!a.archived||a.id===selected)&&(!currency||a.currency===currency));return `<label class="field">Account<select id="${id}">${accounts.map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${esc(a.name)} · ${a.currency}</option>`).join('')}</select></label>`}
function categorySelect(id,kind,selected=''){return `<label class="field">Category<select id="${id}">${db.categories.filter(c=>c.kind===kind).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`}
function err(msg){$('#form-error').textContent=msg;$('#form-error').hidden=false;$('#form-error').focus()}
const errorBox=()=>'<p id="form-error" class="error" role="alert" tabindex="-1" hidden></p>';
function add(mode='quick',edit=null){if(!db.accounts.some(a=>!a.archived)){accountForm('new');return}if(!draft||edit)draft=edit?{...edit,mode:'form',direction:edit.amount<0?'expense':'income',value:(Math.abs(edit.amount)/100).toFixed(2)}:{mode,direction:'expense',account:db.accounts.find(a=>a.currency===ui.currency&&!a.archived)?.id||db.accounts.find(a=>!a.archived).id,date:TODAY,value:'',payee:'',category:'food',raw:''};draft.mode=mode;let form=mode==='quick'?`<label class="field">What happened?<textarea id="quick-text" placeholder="spent 45 on food at the chop bar">${esc(draft.raw||'')}</textarea></label><div class="row between"><span class="small muted">One sentence. You check the details.</span>${iconBtn('mic','voice','About on-device voice capture','soft')}</div>${accountSelect('entry-account',draft.account)}<div id="quick-preview"></div>`:mode==='transfer'?`${accountSelect('entry-from',draft.account)}<label class="field">To account<select id="entry-to"></select></label>${field('Amount','entry-amount',draft.value,'text')}${field('Date','entry-date',draft.date,'date')}<p class="help-block">Transfers stay within one currency. Both sides stay linked.</p>`:`<div class="segmented"><button data-action="direction:expense" class="${draft.direction==='expense'?'selected':''}">Expense</button><button data-action="direction:income" class="${draft.direction==='income'?'selected':''}">Income</button></div>${field('Amount','entry-amount',draft.value,'text')}${accountSelect('entry-account',draft.account,'',!!draft.id)}${categorySelect('entry-category',draft.direction,draft.category)}${field('Payee or note','entry-payee',draft.payee)}${field('Date','entry-date',draft.date,'date')}`;openSheet(draft.id?'Edit transaction':'A little entry',`${!draft.id?`<div class="segmented">${['quick','form','transfer'].map(m=>`<button data-action="capture:${m}" class="${mode===m?'selected':''}">${m==='quick'?'Quick':m==='form'?'Form':'Transfer'}</button>`).join('')}</div>`:''}${form}${errorBox()}${btn(mode==='quick'?'Review & confirm':'Review entry','entry-review','primary full')}${draft.id?`<div class="actions">${btn('Remove transaction','delete:'+draft.id,'danger full')}</div>`:''}`);if(mode==='quick')quickPreview();if(mode==='transfer')transferOptions()}
function captureDraft(){if(!draft)return;if($('#quick-text'))draft.raw=$('#quick-text').value;for(let [id,k]of[['entry-account','account'],['entry-from','account'],['entry-to','to'],['entry-amount','value'],['entry-payee','payee'],['entry-date','date'],['entry-category','category']])if($('#'+id))draft[k]=$('#'+id).value}
function parseQuick(){let text=draft.raw||'',match=text.match(/(?:^|\s)(?:GHS|USD|CAD|NGN|₵|\$|₦)?\s*(\d+(?:,\d{3})*(?:\.\d{1,2})?)(?![\d.])/i),amount=match?toMinor(match[1].replace(/,/g,'')):null,kind=/\b(received|income|earned|paid me|salary)\b/i.test(text)?'income':'expense',category=db.categories.find(c=>c.kind===kind&&c.keywords.split(',').some(k=>k.trim()&&text.toLowerCase().includes(k.trim().toLowerCase())))||db.categories.find(c=>c.kind===kind),payee=text.match(/\b(?:at|from|to)\s+(.+)$/i)?.[1]||category?.name||'Quick entry';return {amount:amount?(kind==='expense'?-amount:amount):0,category:category?.id||'other',payee,account:draft.account,date:/\byesterday\b/i.test(text)?day(TODAY,-1):TODAY,raw:text}}
function quickPreview(){captureDraft();let t=parseQuick(),a=account(t.account),mismatch=draft.raw.match(/\b(GHS|USD|CAD|NGN)\b/i);let valid=t.amount!==0&&(!mismatch||mismatch[1].toUpperCase()===a.currency);$('#quick-preview').innerHTML=t.amount?`<div class="preview-card"><span class="label">Here's what I understood</span><div class="amount number">${money(t.amount,a.currency,true)}</div><div class="od-field"><strong>${esc(t.payee)}</strong><span class="small">${esc(cat(t.category).name)} · ${dateText(t.date)}</span></div><p class="small" style="margin-top:12px">${valid?'Not saved yet. Review before confirming.':'The currency in your sentence does not match this account. Choose another account.'}</p></div>`:'<p class="help-block">Include an amount to see your preview. Nothing saves until you confirm.</p>'; $('[data-action="entry-review"]').disabled=!valid}
function transferOptions(){let from=$('#entry-from').value,a=account(from),to=$('#entry-to');to.innerHTML=db.accounts.filter(b=>b.id!==from&&!b.archived&&b.currency===a.currency).map(b=>`<option value="${b.id}">${esc(b.name)} · ${b.currency}</option>`).join('')||'<option value="">No other account in this currency</option>';if(draft.to&&Array.from(to.options).some(o=>o.value===draft.to))to.value=draft.to}
function reviewEntry(){captureDraft();let t;if(draft.mode==='quick')t=parseQuick();else{let n=toMinor(draft.value);if(n===null||n<=0){err('Enter an amount greater than zero, with at most two decimal places.');return}t={...draft,amount:n*(draft.direction==='expense'||draft.mode==='transfer'?-1:1)}}if(!t.amount){err('Include an amount greater than zero.');return}if(!t.date||!/^\d{4}-\d{2}-\d{2}$/.test(t.date)){err('Choose a date for this entry.');return}if(draft.mode==='transfer'&&(!draft.to||draft.to===draft.account||account(draft.to).currency!==account(draft.account).currency)){err('Choose a different account in the same currency.');return}if(draft.id&&draft.pair&&account(t.account).currency!==account(db.tx.find(x=>x.pair===draft.pair&&x.id!==draft.id).account).currency){err('Both sides of a transfer must stay in the same currency.');return}let a=account(t.account);if(draft.mode==='transfer'){t.to=draft.to;t.payee='Transfer to '+account(t.to).name;t.category='other'}confirmation(draft.id?'Save these changes?':'Check your entry',`<div class="preview-card"><span class="label">${draft.mode==='transfer'?'Transfer':t.amount<0?'Money out':'Money in'}</span><div class="amount number">${money(t.amount,a.currency,true)}</div><dl class="detail-list"><dt>${t.to?'From':'Account'}</dt><dd>${esc(a.name)}</dd>${t.to?`<dt>To</dt><dd>${esc(account(t.to).name)}</dd>`:`<dt>Category</dt><dd>${esc(cat(t.category).name)}</dd><dt>Payee / note</dt><dd>${esc(t.payee||cat(t.category).name)}</dd>`}<dt>Date</dt><dd>${fullDate(t.date)}</dd></dl>${t.raw?`<p class="quote">“${esc(t.raw)}”</p>`:''}</div><p class="help-block">${t.date>TODAY?'Scheduled for the future. Your current balance stays unchanged until that date.':'Only confirmed entries become part of your ledger.'}</p>`,()=>{if(draft.id){let existing=db.tx.find(x=>x.id===draft.id);Object.assign(existing,{account:t.account,amount:t.amount,date:t.date,category:t.category,payee:t.payee,raw:t.raw});if(existing.pair){let other=db.tx.find(x=>x.pair===existing.pair&&x.id!==existing.id);if(other){other.amount=-existing.amount;other.date=existing.date}}}else if(t.to){let pair=uid();db.tx.push({id:uid(),pair,account:t.account,amount:t.amount,date:t.date,category:'other',payee:'Transfer to '+account(t.to).name},{id:uid(),pair,account:t.to,amount:-t.amount,date:t.date,category:'other',payee:'Transfer from '+a.name})}else db.tx.push({id:uid(),account:t.account,amount:t.amount,date:t.date,category:t.category,payee:t.payee||cat(t.category).name,raw:t.raw||''});draft=null;persist();closeSheet(false);render();toast('Entry saved. Everything is up to date.');$('#nav button')?.focus()},'Confirm & save',()=>add(draft.mode))}
function confirmation(title,html,action,label='Confirm',back=null){confirmAction=action;openSheet(title,html+`<div class="actions">${btn(back?'Edit details':'Cancel',back?'confirmation-back':'close','secondary')}${btn(label,'confirm','primary')}</div>`);confirmAction=action;window.confirmBack=back}
function accountForm(id){let a=db.accounts.find(x=>x.id===id),exists=!!a;a=a||{name:'',type:'Bank',currency:ui.currency||db.defaultCurrency,opening:0};openSheet(exists?'Your account':'A new pocket',`${exists?`<div class="amount number" style="margin-bottom:24px">${money(balance(a.id),a.currency)}</div>`:''}${field('Account name','account-name',a.name)}<label class="field">Type<select id="account-type">${['Bank','Mobile money','Savings','Cash'].map(t=>`<option ${a.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Currency<select id="account-currency" ${exists?'disabled':''}>${['GHS','USD','CAD','NGN'].map(c=>`<option ${c===a.currency?'selected':''}>${c}</option>`).join('')}</select><span class="help">${exists?'Currency stays fixed so history stays honest.':'Currency cannot change after creation.'}</span></label>${exists?'':field('Opening balance','account-opening','0.00','text')}${errorBox()}${btn('Save account','account-save:'+id,'primary full')}${exists?`<div class="actions">${btn(a.archived?'Unarchive account':'Archive account','account-archive:'+id,'secondary full')}</div>`:''}`)}
function budgetForm(id){let b=db.budgets.find(x=>x.category===id&&x.currency===ui.currency&&x.month===ui.month);openSheet(b?'A flexible plan':'Set a budget',`<p class="help-block">${monthLabel()} · ${ui.currency}</p>${categorySelect('budget-category','expense',b?.category)}${field('Budget amount ('+ui.currency+')','budget-amount',b?(b.amount/100).toFixed(2):'','text')}${errorBox()}${btn('Save budget','budget-save','primary full')}${b?`<div class="actions">${btn('Clear budget','budget-clear:'+id,'secondary full')}</div>`:''}`)}
function categoryForm(id){let c=db.categories.find(x=>x.id===id)||{name:'',kind:ui.categoryKind,icon:'other',keywords:''};openSheet(id==='new'?'New category':'Make it yours',`${field('Name','category-name',c.name)}<label class="field">Kind<select id="category-kind"><option value="expense" ${c.kind==='expense'?'selected':''}>Expense</option><option value="income" ${c.kind==='income'?'selected':''}>Income</option></select></label><label class="field">Icon<select id="category-icon">${['food','transport','shopping','family','bills','airtime','income','work','goal','other'].map(n=>`<option value="${n}" ${n===c.icon?'selected':''}>${n}</option>`).join('')}</select></label>${field('Words you use','category-keywords',c.keywords,'text','Separate with commas. For example: lunch, chop bar, kfc. Quick capture uses these words to suggest this category.')}<p class="help-block">Category icons work without colour. Their tint follows your theme.</p>${errorBox()}${btn('Save category','category-save:'+id,'primary full')}`)}
function expectedForm(id){let e=db.expected.find(x=>x.id===id);if(e){openSheet('Still on the way',`<div class="pending"><span class="label">Expected · not received</span><h3 style="margin-top:16px">${esc(e.name)}</h3><div class="amount number" style="margin:16px 0">${money(e.amount,account(e.account).currency)}</div><p class="small">${e.date<TODAY?delta(TODAY,e.date)+' days late':'Due '+fullDate(e.date)}</p></div><p class="help-block">Has this money arrived? You’ll check the details before it enters your ledger.</p>${btn('Received '+icon('check'),'receive:'+id,'primary full')}<div class="actions">${btn('Edit promise','expected-edit:'+id,'secondary')}${btn('Remove','expected-remove:'+id,'secondary')}</div>`);return}expectedEdit('new')}
function expectedEdit(id){let e=db.expected.find(x=>x.id===id)||{name:'',amount:0,account:db.accounts.find(a=>!a.archived)?.id,date:TODAY};if(!e.account){accountForm('new');return}openSheet(id==='new'?'Money you expect':'Edit expected money',`${field('Who or what is it from?','expected-name',e.name)}${field('Amount','expected-amount',e.amount?(e.amount/100).toFixed(2):'','text')}${accountSelect('expected-account',e.account)}${field('Expected date','expected-date',e.date,'date')}${errorBox()}${btn('Save expected money','expected-save:'+id,'primary full')}`)}
function ruleForm(id){let r=db.rules.find(x=>x.id===id)||{name:'',amount:-1,account:db.accounts.find(a=>!a.archived)?.id,date:TODAY,frequency:'monthly'};if(!r.account){accountForm('new');return}openSheet(id==='new'?'A familiar rhythm':'Recurring payment',`${field('Name','rule-name',r.name)}<label class="field">Direction<select id="rule-direction"><option value="expense" ${r.amount<0?'selected':''}>Money out</option><option value="income" ${r.amount>0?'selected':''}>Money in</option></select></label>${field('Amount','rule-amount',r.amount===-1?'':(Math.abs(r.amount)/100).toFixed(2),'text')}${accountSelect('rule-account',r.account)}${field('Next date','rule-date',r.date,'date')}<label class="field">Repeats<select id="rule-frequency"><option value="monthly" ${r.frequency==='monthly'?'selected':''}>Monthly</option><option value="weekly" ${r.frequency==='weekly'?'selected':''}>Weekly</option></select></label><p class="help-block">Appears in your plan. Recording an actual payment still needs your confirmation.</p>${errorBox()}${btn('Save recurring rule','rule-save:'+id,'primary full')}${id!=='new'?`<div class="actions">${btn('Remove rule','rule-remove:'+id,'secondary full')}</div>`:''}`)}
function goalForm(id){let g=db.goals.find(x=>x.id===id)||{name:'',target:0,saved:0,currency:ui.currency,date:'2027-03-01'};openSheet(id==='new'?'Make room for a goal':'A little closer',`${field('What are you saving for?','goal-name',g.name)}<label class="field">Currency<select id="goal-currency">${['GHS','USD','CAD','NGN'].map(c=>`<option ${c===g.currency?'selected':''}>${c}</option>`).join('')}</select></label>${field('Target amount','goal-target',g.target?(g.target/100).toFixed(2):'','text')}${field('Already set aside','goal-saved',(g.saved/100).toFixed(2),'text','A reservation in your plan. This does not move or create money.')}${field('Target date','goal-date',g.date,'date')}${errorBox()}${btn('Save goal','goal-save:'+id,'primary full')}${id!=='new'?`<div class="actions">${btn('Remove reservation','goal-remove:'+id,'secondary full')}</div>`:''}`)}
function parseCSV(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){row.push(cell.trim());cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=ch}if(cell||row.length){row.push(cell.trim());rows.push(row)}if(quoted)throw Error('A quoted cell is not closed. Please correct the CSV and try again.');return rows}
function contentKey(t){return [t.account,t.date,t.amount,String(t.payee||'').trim().toLowerCase().replace(/\s+/g,' ')].join('|')}
function importScreen(){if(!db.accounts.some(a=>!a.archived))return childHeading('Import a statement','settings')+empty('Start with an account','Choose where these transactions belong.','account:new','Add an account');if(!importBatch)return childHeading('Import a statement','settings')+`<div class="tutorial"><h2>Bring the past along.</h2><p class="help-block">Choose a CSV file from your bank or mobile money statement. You'll map its columns and review every result before anything is added.</p></div><label class="field" style="margin-top:24px">Statement CSV<input type="file" id="csv-file" accept=".csv,text/csv"></label><p class="notice">Use a dated statement with a signed amount column: negative for expenses, positive for income. Dates should be YYYY-MM-DD. Values use a decimal point and at most two decimal places.</p><div class="screen-actions">${btn('Try an example CSV','csv-example','secondary full')}</div><p id="import-error" role="alert" class="error" hidden></p>`;let b=importBatch;if(b.stage==='map'){let options=(id,label,guess)=>`<label class="field">${label}<select id="${id}">${b.headers.map((h,i)=>`<option value="${i}" ${guess===i?'selected':''}>${esc(h||'Column '+(i+1))}</option>`).join('')}</select></label>`;return childHeading('Match your columns','settings')+`<p class="help-block">${b.rows.length} rows · ${esc(b.filename)}<br>Mappings are remembered for this column layout.</p>${accountSelect('csv-account',b.account||db.accounts.find(a=>!a.archived).id)}${options('csv-date','Transaction date',b.mapping.date)}${options('csv-payee','Payee or description',b.mapping.payee)}${options('csv-amount','Signed amount',b.mapping.amount)}<p class="notice">One statement belongs to one account and currency. Transfers are not auto-linked; review them before importing.</p><p id="import-error" role="alert" class="error" hidden></p><div class="actions">${btn('Start over','import-reset','secondary')}${btn('Review rows','csv-review','primary')}</div>`}return childHeading('Check your statement','settings')+`<div class="card surface"><h2>${b.ready.length} ready</h2><p class="help-block" style="margin-bottom:0">${b.duplicates} duplicates · ${b.errors.length} unreadable<br>${esc(account(b.account).name)} · ${account(b.account).currency}</p></div><p class="help-block">${b.ready.length?'Only the ready rows below will be added.':'Nothing new to import. Your ledger stays unchanged.'} Duplicate and unreadable rows are skipped.</p>${b.ready.slice(0,30).map(t=>`<div class="review-row"><div class="row between"><strong class="od-truncate">${esc(t.payee)}</strong><span class="money">${money(t.amount,account(t.account).currency,true)}</span></div><small>${fullDate(t.date)}</small></div>`).join('')}${b.ready.length>30?`<p class="help-block">Showing the first 30 of ${b.ready.length} ready rows.</p>`:''}${b.errors.length?`<details class="disclosure"><summary>${b.errors.length} unreadable rows ${icon('down')}</summary>${b.errors.map(e=>`<p>Row ${e.row}: ${esc(e.message)}</p>`).join('')}</details>`:''}<div class="actions">${btn('Change mapping','csv-remap','secondary')}<button class="primary" data-action="csv-commit" ${!b.ready.length?'disabled':''}>Confirm import</button></div>`}
function loadCSV(text,filename){try{let rows=parseCSV(text.replace(/^\uFEFF/,''));if(rows.length<2)throw Error('Include a header and at least one transaction row.');let headers=rows.shift(),signature=headers.map(h=>h.toLowerCase()).join('|'),saved=db.mappings[signature];let find=(re,fallback)=>{let i=headers.findIndex(h=>re.test(h));return i>=0?i:fallback};importBatch={headers,rows,filename,signature,stage:'map',mapping:saved||{date:find(/date/i,0),payee:find(/payee|description|note|name/i,1),amount:find(/amount|value|total/i,2)}};render()}catch(e){$('#import-error').hidden=false;$('#import-error').textContent=e.message}}
function csvReview(){let b=importBatch,m={date:Number($('#csv-date').value),payee:Number($('#csv-payee').value),amount:Number($('#csv-amount').value)};if(new Set(Object.values(m)).size<3){$('#import-error').hidden=false;$('#import-error').textContent='Choose a different column for each field.';return}b.mapping=m;b.account=$('#csv-account').value;b.ready=[];b.errors=[];b.duplicates=0;let known=new Set(db.tx.map(contentKey));b.rows.forEach((r,i)=>{let date=(r[m.date]||'').trim(),amount=toMinor((r[m.amount]||'').replace(/,/g,'')),payee=r[m.payee]||'';if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date+'T12:00Z'))||new Date(date+'T12:00Z').toISOString().slice(0,10)!==date||amount===null||!amount||!payee.trim()){b.errors.push({row:i+2,message:'Use a valid ISO date, non-zero amount and description.'});return}let category=db.categories.find(c=>c.kind===(amount<0?'expense':'income')&&c.keywords.split(',').some(k=>k.trim()&&payee.toLowerCase().includes(k.trim().toLowerCase())))?.id||(amount>0?db.categories.find(c=>c.kind==='income')?.id:'other')||'other',t={id:uid(),date,amount,payee,account:b.account,category,source:'CSV import'};if(known.has(contentKey(t)))b.duplicates++;else{known.add(contentKey(t));b.ready.push(t)}});db.mappings[b.signature]=m;persist();b.stage='review';render()}
function download(name,text,type){let blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Download requested. Keep your file somewhere safe.')}
function exportCSV(){let quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';let rows=[['date','payee','amount','currency','account','category','note','transfer_id'],...activeTx().map(t=>[t.date,t.payee,(t.amount/100).toFixed(2),account(t.account).currency,account(t.account).name,cat(t.category).name,t.raw||'',t.pair||''])];download('gally-ledger.csv',rows.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function backup(){db.lastBackup=TODAY;persist();download('gally-backup-2026-11-20.json',JSON.stringify(db,null,2),'application/json')}
function restoreStart(){openSheet('Bring back your file',`<p class="help-block">Restore a Gally prototype JSON backup. This replaces the current ledger, accounts, plans and preferences. It does not merge them.</p><p class="notice">Create a backup of your current file first if you may need it again.</p><label class="field" style="margin-top:24px">Backup file<input type="file" id="restore-file" accept=".json,application/json"></label><p id="restore-error" class="error" role="alert" hidden></p>${btn('Back up current data','backup','secondary full')}`)}
function validBackup(d){if(!d||d.version!==1||!['light','dark'].includes(d.theme)||!['GHS','USD','CAD','NGN'].includes(d.defaultCurrency))return false;for(let k of ['accounts','tx','categories','budgets','expected','rules','goals','importKeys'])if(!Array.isArray(d[k]))return false;let ids=new Set(d.accounts.map(a=>a.id));return ids.size===d.accounts.length&&d.accounts.every(a=>typeof a.id==='string'&&typeof a.name==='string'&&['GHS','USD','CAD','NGN'].includes(a.currency)&&Number.isSafeInteger(a.opening))&&d.categories.every(c=>['name','kind','icon','keywords','id'].every(k=>typeof c[k]==='string'))&&d.tx.every(t=>typeof t.id==='string'&&ids.has(t.account)&&Number.isSafeInteger(t.amount)&&/^\d{4}-\d{2}-\d{2}$/.test(t.date))&&d.expected.every(e=>ids.has(e.account)&&Number.isSafeInteger(e.amount)&&e.amount>0&&typeof e.name==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(e.date))&&d.rules.every(r=>ids.has(r.account)&&Number.isSafeInteger(r.amount)&&['weekly','monthly'].includes(r.frequency)&&typeof r.name==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.date))&&validBudgetBackup(d)&&validSubscriptionBackup(d)&&d.goals.every(g=>Number.isSafeInteger(g.target)&&Number.isSafeInteger(g.saved)&&g.target>0&&g.saved>=0&&typeof g.name==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(g.date))}
function removed(){let rows=db.tx.filter(t=>t.deleted);openSheet('Recently removed',`<p class="help-block">Removed from your ledger, still in your file. Restoring either side of a transfer brings both sides back.</p>${rows.length?rows.map(t=>`<div class="list-row"><span class="od-field od-fill"><strong>${esc(t.payee)}</strong><small>${money(t.amount,account(t.account)?.currency||'GHS',true)}</small></span>${btn('Restore','undelete:'+t.id,'text-btn')}</div>`).join(''):'<p class="notice">No removed transactions.</p>'}`)}
function safeSheet(){let s=safety();openSheet('Room to spend',`<span class="label">${s.safe<0?'Shortfall after commitments':'Safe to spend'}</span><div class="amount number" style="margin:16px 0">${money(s.safe)}</div><p class="help-block">What's left after obligations due before ${s.income?'your next scheduled income on '+dateText(s.until):dateText(s.until)+' (no scheduled income in the next 180 days)'} and money reserved for goals.</p><dl class="detail-list"><dt>Recorded balances</dt><dd class="money">${money(s.available)}</dd><dt>Committed before then</dt><dd class="money">−${money(s.due)}</dd><dt>Reserved for goals</dt><dd class="money">−${money(s.reserved)}</dd><dt>${s.safe<0?'Shortfall':'Available after these'}</dt><dd class="money">${money(s.safe)}</dd></dl><div class="notice">Expected payments are excluded. This is a planning calculation, not a daily spending allowance. It only knows what you have recorded.</div><div class="actions">${btn('See the forecast','page:forecast','primary full')}</div>`)}
function currencyPicker(defaultOnly=false){openSheet(defaultOnly?'Your default currency':'One currency at a time',`<p class="help-block">${defaultOnly?'Preselects the currency for new accounts. Existing accounts stay unchanged.':'Switch the view without combining or converting your money.'}</p><div class="stack">${['GHS','USD','CAD','NGN'].map(c=>btn(c+' · '+({GHS:'Ghanaian cedi',USD:'US dollar',CAD:'Canadian dollar',NGN:'Nigerian naira'}[c]),(defaultOnly?'default-set:':'currency-set:')+c,'secondary full')).join('')}</div>`)}
function deleteTx(id){let t=db.tx.find(t=>t.id===id);confirmation('Remove this entry?',`<p class="help-block">${t.pair?'Both sides of this transfer will leave your ledger.':'This transaction will leave your ledger.'} It stays in your file and can be restored from Recently removed.</p>`,()=>{if(t.subscription){let sub=db.subscriptions.find(s=>s.id===t.subscription);if(sub&&sub.nextRenewal===advanceCycle(t.renewalDate,sub.cycle,sub.anchor||t.renewalDate))sub.nextRenewal=t.renewalDate}db.tx.forEach(x=>{if(x.id===id||(t.pair&&x.pair===t.pair))x.deleted=TODAY});persist();closeSheet(false);draft=null;render();toast('Removed from your ledger. Still in your file.');$('#nav button')?.focus()},'Remove entry')}
function showFilters(){openSheet('Find what you need',`<label class="field">Account<select id="filter-account"><option value="">All accounts</option>${db.accounts.map(a=>`<option value="${a.id}" ${a.id===ui.accountFilter?'selected':''}>${esc(a.name)} · ${a.currency}</option>`).join('')}</select></label><label class="field">Category<select id="filter-category"><option value="">All categories</option>${db.categories.map(c=>`<option value="${c.id}" ${c.id===ui.catFilter?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="actions">${btn('Clear filters','filters-clear','secondary')}${btn('Apply filters','filters-apply','primary')}</div>`)}
function saveSimple(type,id){let name=$('#'+type+'-name')?.value.trim();if(type==='account'){let a=db.accounts.find(x=>x.id===id),opening=toMinor($('#account-opening')?.value||'0');if(!name||opening===null){err('Enter a name and an opening balance with at most two decimal places.');return}if(a)Object.assign(a,{name,type:$('#account-type').value});else db.accounts.push({id:uid(),name,type:$('#account-type').value,currency:$('#account-currency').value,opening})}
if(type==='category'){if(!name){err('Give this category a name.');return}let c={id:id==='new'?uid():id,name,kind:$('#category-kind').value,icon:$('#category-icon').value,keywords:$('#category-keywords').value};if(id==='new')db.categories.push(c);else Object.assign(db.categories.find(x=>x.id===id),c)}
if(type==='expected'||type==='rule'){let amount=toMinor($('#'+type+'-amount').value),date=$('#'+type+'-date').value;if(!name||amount===null||amount<=0||!date){err('Add a name, positive amount and valid date.');return}let o={id:id==='new'?uid():id,name,amount,account:$('#'+type+'-account').value,date,category:type==='expected'?'freelance':$('#rule-direction').value==='income'?'salary':'bills'};if(type==='rule'){o.amount*= $('#rule-direction').value==='expense'?-1:1;o.frequency=$('#rule-frequency').value}let list=type==='expected'?db.expected:db.rules;if(id==='new')list.push(o);else Object.assign(list.find(x=>x.id===id),o)}
if(type==='goal'){let target=toMinor($('#goal-target').value),saved=toMinor($('#goal-saved').value),date=$('#goal-date').value;if(!name||target===null||target<=0||saved===null||saved<0||!date||date<TODAY){err('Add a name, positive target, non-negative reservation and a target date from today onward.');return}let g={id:id==='new'?uid():id,name,target,saved,date,currency:$('#goal-currency').value};if(id==='new')db.goals.push(g);else Object.assign(db.goals.find(x=>x.id===id),g)}persist();closeSheet(false);render();toast('Saved. Your plan is up to date.');$('#nav button')?.focus()}
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el||el.disabled)return;let action=el.dataset.action,[a,id]=action.split(':');switch(a){
case'page':nav(id);break;
case'home':ui.page='home';ui.homeTab=id;render();break;
case'add':draft=null;add();break;
case'capture':captureDraft();add(id);break;
case'direction':captureDraft();draft.direction=id;draft.category=db.categories.find(c=>c.kind===id)?.id;add('form');break;
case'entry-review':reviewEntry();break;
case'edit':{let t=db.tx.find(t=>t.id===id);draft=null;add('form',t);break}
case'close':closeSheet();break;
case'confirm':{let fn=confirmAction;if(fn)fn();break}
case'confirmation-back':window.confirmBack?.();break;
case'theme':db.theme=db.theme==='light'?'dark':'light';persist();render();break;
case'hide':db.hidden=!db.hidden;persist();render();toast(db.hidden?'Balances hidden. Tap the eye to show them.':'Balances visible.');break;
case'currency':currencyPicker();break;
case'default-currency':currencyPicker(true);break;
case'currency-set':ui.currency=id;ui.forecastAccount='';closeSheet(false);render();break;
case'default-set':db.defaultCurrency=id;persist();closeSheet(false);render();toast('Default currency updated.');break;
case'month':{let d=new Date(ui.month+'-01T12:00Z');d.setUTCMonth(d.getUTCMonth()+Number(id));let next=d.toISOString().slice(0,7);if(next<=MAX_MONTH){ui.month=next;render()}else toast('Future dashboard months are not available. Use Look ahead to plan.');break}
case'filter':ui.filter=id;render();break;
case'filters':showFilters();break;
case'filters-apply':ui.accountFilter=$('#filter-account').value;ui.catFilter=$('#filter-category').value;closeSheet(false);render();break;
case'filters-clear':ui.accountFilter='';ui.catFilter='';closeSheet(false);render();break;
case'account':accountForm(id);break;
case'account-save':saveSimple('account',id);break;
case'account-archive':{let a=account(id);a.archived=!a.archived;persist();closeSheet(false);render();toast(a.archived?'Archived. Your history stays in your file.':'Account unarchived.');break}
case'budget':budgetForm(id);break;
case'budget-save':{let n=toMinor($('#budget-amount').value),c=$('#budget-category').value;if(n===null||n<=0){err('Enter a budget greater than zero, with at most two decimal places.');return}let b=db.budgets.find(x=>x.category===c&&x.month===ui.month&&x.currency===ui.currency);if(b)b.amount=n;else db.budgets.push({category:c,month:ui.month,currency:ui.currency,amount:n});persist();closeSheet(false);render();toast('Budget saved. It can change when life does.');break}
case'budget-clear':db.budgets=db.budgets.filter(b=>!(b.category===id&&b.month===ui.month&&b.currency===ui.currency));persist();closeSheet(false);render();break;
case'category-kind':ui.categoryKind=id;render();break;
case'category':categoryForm(id);break;
case'category-save':saveSimple('category',id);break;
case'expected':expectedForm(id);break;
case'expected-edit':expectedEdit(id);break;
case'expected-save':saveSimple('expected',id);break;
case'expected-remove':confirmation('Remove this expectation?','<p class="help-block">Recorded balances stay unchanged. This promise will leave your plan.</p>',()=>{db.expected=db.expected.filter(x=>x.id!==id);persist();closeSheet(false);render();toast('Expected payment removed from your plan.')},'Remove expectation');break;
case'receive':{let x=db.expected.find(x=>x.id===id);confirmation('Has this money arrived?',`<div class="preview-card"><span class="label">Money received</span><div class="amount number">${money(x.amount,account(x.account).currency,true)}</div><p>${esc(x.name)}</p><p class="small" style="margin-top:8px">${esc(account(x.account).name)} · ${fullDate(TODAY)}</p></div><p class="help-block">This will become a real transaction and leave your expected list.</p>`,()=>{db.tx.push({id:uid(),account:x.account,amount:x.amount,date:TODAY,payee:x.name,category:x.category||'freelance'});db.expected=db.expected.filter(e=>e.id!==id);persist();closeSheet(false);render();toast('Received. Now part of your balance.')},'Confirm received');break}
case'rule':ruleForm(id);break;
case'rule-save':saveSimple('rule',id);break;
case'rule-remove':confirmation('Remove this recurring rule?','<p class="help-block">It will leave your forecast. Past transactions stay exactly as they are.</p>',()=>{db.rules=db.rules.filter(r=>r.id!==id);persist();closeSheet(false);render()},'Remove rule');break;
case'goal':goalForm(id);break;
case'goal-save':saveSimple('goal',id);break;
case'goal-remove':confirmation('Release this reservation?','<p class="help-block">This goal will leave your plan, and its reserved amount returns to safe-to-spend. Account balances will not change.</p>',()=>{db.goals=db.goals.filter(g=>g.id!==id);persist();closeSheet(false);render()},'Release reservation');break;
case'safe':safeSheet();break;
case'horizon':ui.horizon=Number(id);render();break;
case'scenario':ui.page='forecast';ui.scenario=true;ui.late=14;closeSheet(false);render();$('#content').scrollTop=0;break;
case'scenario-update':{let extra=toMinor($('#scenario-extra').value),loan=toMinor($('#scenario-loan').value);if(extra===null||extra<0||loan===null||loan<0){toast('Use non-negative amounts with at most two decimal places.');return}ui.late=Number($('#scenario-late').value);ui.incomeReduction=Number($('#scenario-reduction').value);ui.extra=extra;ui.loan=loan;ui.loanMonths=Number($('#scenario-months').value);render();break}
case'scenario-reset':ui.late=0;ui.incomeReduction=0;ui.extra=0;ui.loan=0;render();break;
case'scenario-exit':ui.scenario=false;render();break;
case'forecast-day':{let d=day(TODAY,Number(id)),f=forecastData(),items=f.events.filter(e=>e.date===d);openSheet(fullDate(d),`<h3>${f.arr[Number(id)]<0?'A projected shortfall':'Your projected day'}</h3><div class="amount number" style="margin:16px 0">${money(f.arr[Number(id)])}</div>${items.map(e=>`<div class="list-row"><span class="od-field od-fill"><strong>${esc(e.name)}</strong><small>${e.type}</small></span><span class="money">${money(e.amount,ui.currency,true)}</span></div>`).join('')||'<p class="help-block">No dated events on this day. This balance carries forward from earlier events.</p>'}<p class="help-block">Expected money is excluded from this balance.</p>`);break}
case'voice':openSheet('Say it. Then check it.',`<span class="category-icon">${icon('mic')}</span><p class="help-block">In the Android app, hold the microphone to dictate on your device, then check the same preview before saving.</p><p class="notice">This browser prototype does not access your microphone or send audio anywhere. To try the flow, type the words you would say in Quick entry.</p>${btn('Try Quick entry','voice-return','primary full')}`);break;
case'voice-return':add('quick');break;
case'delete':deleteTx(id);break;
case'undelete':{let t=db.tx.find(x=>x.id===id);if(t.subscription){let sub=db.subscriptions.find(s=>s.id===t.subscription);if(sub&&sub.nextRenewal===t.renewalDate)sub.nextRenewal=advanceCycle(t.renewalDate,sub.cycle,sub.anchor||t.renewalDate)}db.tx.forEach(x=>{if(x.id===id||(t.pair&&t.pair===x.pair))delete x.deleted});persist();render();removed();toast('Restored to your ledger.');break}
case'removed':removed();break;
case'export-csv':exportCSV();break;
case'backup':backup();break;
case'reminder':db.notifications=!db.notifications;persist();render();toast(db.notifications?'In-app reminder enabled. Native notification delivery is specified in the handoff.':'Backup reminder turned off.');break;
case'restore':restoreStart();break;
case'restore-final':confirmation('Replace the current file?',`<p class="help-block">Final confirmation. Replace current data with ${restoreData.tx.length} transaction records and ${restoreData.accounts.length} accounts from this backup. This does not merge ledgers.</p>`,()=>{db=restoreData;restoreData=null;storageIssue='';rawRecovery='';db.mappings=db.mappings||{};db.importKeys=db.importKeys||[];persist();ui.page='home';ui.currency=db.defaultCurrency;closeSheet(false);render();toast('Backup restored. Your previous ledger was replaced.')},'Replace my ledger');break;
case'wipe':confirmation('Start with a clean ledger?',`<p class="help-block">This removes active money data from the app. Preferences and remembered import mappings remain. A recoverable snapshot stays inside your exported prototype file.</p>${btn('Back up first','backup','secondary full')}`,()=>{openSheet('One last check',`<p class="help-block">Type WIPE to confirm. Your accounts, active ledger, budgets and plans will be cleared.</p>${field('Type WIPE','wipe-word')}${errorBox()}${btn('Wipe money data','wipe-final','danger full')}`)},'Continue');break;
case'wipe-final':if($('#wipe-word').value!=='WIPE'){err('Type WIPE exactly to confirm.');return}db.removedData={accounts:db.accounts,tx:db.tx,budgets:db.budgets,rules:db.rules,goals:db.goals,expected:db.expected,subscriptions:db.subscriptions};for(let k of ['accounts','tx','budgets','rules','goals','expected','subscriptions'])db[k]=[];db.guidedSetup=null;plannerUI.chat=[];persist();draft=null;ui.page='home';closeSheet(false);render();toast('A clean ledger. Preferences and mappings kept.');break;
case'demo':{beginDemo();break;}
case'legacy-demo-merge':{let example=seed();for(let k of ['accounts','tx','categories','budgets','expected','rules','goals'])for(let item of example[k]){let key=k==='budgets'?x=>x.category===item.category&&x.currency===item.currency&&x.month===item.month:x=>x.id===item.id;if(!db[k].some(key))db[k].push(item)}persist();render();toast('Example data loaded. Existing entries were kept.');break}
case'csv-example':loadCSV('Date,Description,Amount\n2026-11-18,Trotro to work,-60.00\n2026-11-19,Client payment,1500.00\nnot-a-date,Unreadable row,wrong\n2026-11-19,Client payment,1500.00','example-statement.csv');break;
case'csv-review':csvReview();break;
case'csv-remap':importBatch.stage='map';render();break;
case'import-reset':importBatch=null;render();break;
case'csv-commit':{let b=importBatch;if(!b?.ready.length)return;let known=new Set(db.tx.map(contentKey)),rows=b.ready.filter(t=>!known.has(contentKey(t)));db.tx.push(...rows);persist();importBatch=null;ui.page='ledger';closeSheet(false);render();toast(rows.length+' transactions imported. Duplicates skipped.');break}
}});
document.addEventListener('input',e=>{if(e.target.id==='quick-text')quickPreview();if(e.target.id==='ledger-search'){let pos=e.target.selectionStart;ui.search=e.target.value;render();let input=$('#ledger-search');input.focus();input.setSelectionRange(pos,pos)}if(e.target.id==='scenario-late')$('#late-label').textContent=e.target.value+' days'});
document.addEventListener('change',async e=>{let id=e.target.id;if(id==='entry-account'&&draft?.mode==='quick')quickPreview();if(id==='entry-from')transferOptions();if(id==='forecast-account'){ui.forecastAccount=e.target.value;render()}if(id==='csv-file'&&e.target.files[0]){let f=e.target.files[0];try{showImportReading(f.name);const contents=await f.text();loadCSV(contents,f.name)}catch{$('#import-error').hidden=false;$('#import-error').textContent='Could not read this file. Try another CSV.'}}if(id==='restore-file'&&e.target.files[0]){try{let d=JSON.parse(await e.target.files[0].text());if(!validBackup(d))throw Error('Choose a complete Gally prototype backup with valid account and transaction data.');restoreData=d;openSheet('Review your backup',`<p class="help-block">This file contains ${d.accounts.length} accounts, ${d.tx.length} transaction records and ${d.goals.length} goals.</p><p class="notice">Restore replaces your current ledger. It does not merge. You will confirm once more before replacement.</p><div class="actions">${btn('Cancel','close','secondary')}${btn('Continue to restore','restore-final','primary')}</div>`)}catch(err){$('#restore-error').hidden=false;$('#restore-error').textContent=err.message}}});
document.addEventListener('keydown',e=>{if(!$('#overlay').hidden){if(e.key==='Escape'){e.preventDefault();closeSheet();return}if(e.key==='Tab'){let focusable=Array.from($('#overlay').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea,a[href],[tabindex="0"]')).filter(n=>n.getClientRects().length),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if(e.key==='Enter'&&e.target.tagName==='INPUT'&&!['file','range'].includes(e.target.type)){let action=$('#sheet-body [data-action="entry-review"]')||$('#sheet-body .primary');if(action&&!action.disabled){e.preventDefault();action.click()}}}});
$('#overlay').addEventListener('click',e=>{if(e.target.id==='overlay')closeSheet()});
ui.currency=db.defaultCurrency||'GHS';
render();
globalThis.gallyBooted=true;
playSplash();
if(db.notifications&&(!db.lastBackup||delta(TODAY,db.lastBackup)>=7))setTimeout(()=>toast('A little backup goes a long way. Create one in Settings.'),1000);

function homeExpectedCard(){let e=db.expected.find(x=>account(x.account)?.currency===ui.currency);return e?`<button class="pending full" data-action="expected:${e.id}" style="text-align:left"><span class="row between"><span class="pending-state">${icon('clock')}Expected · not received</span>${icon('chevron')}</span><span class="od-field" style="margin-top:12px"><strong>${esc(e.name)}</strong><span class="money sensitive">${money(e.amount)}</span><span class="small">${e.date<TODAY?delta(TODAY,e.date)+' days late':e.date===TODAY?'Due today':'Due '+dateText(e.date)} · excluded from your balance</span></span></button>`:`<div class="card surface"><p class="help-block">Nothing expected yet. Add a payment you're waiting for.</p>${btn('Add expected money','expected:new','text-btn')}</div>`}
